modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    giraffe_patches = image_patch.find("giraffe")

    if len(giraffe_patches) < 2:
        return image_patch

    # Sort giraffes based on their vertical center
    giraffe_patches.sort(key=lambda g: g.vertical_center)

    # Find the pair of giraffes closest to each other vertically
    min_distance = float('inf')
    closest_pair = None

    for i in range(len(giraffe_patches)):
        for j in range(i + 1, len(giraffe_patches)):
            dist = abs(giraffe_patches[i].vertical_center - giraffe_patches[j].vertical_center)
            if dist < min_distance:
                min_distance = dist
                closest_pair = (giraffe_patches[i], giraffe_patches[j])

    # Check if they are close enough horizontally to be considered talking
    if abs(closest_pair[0].horizontal_center - closest_pair[1].horizontal_center) <= min_distance * 2:
        return closest_pair[0]

    return image_patch

